// FUNCTION: BFME2 0x00497A4B size=157 name=?createVisionObject@BattlePlanUpdate@@QAEXXZ evidence=N:ledger tier=A
void BattlePlanUpdate::createVisionObject()
{
	if (m_visionObjectID != INVALID_ID)
		return;
	const BattlePlanUpdateModuleData *data = (const BattlePlanUpdateModuleData *)getModuleData();
	Object *owner = getObject();
	const ThingTemplate *visionTemplate = TheThingFactory->findTemplate(data->m_visionObjectName);
	if (!visionTemplate)
		return;
	Player *neutralPlayer = ThePlayerList->getNeutralPlayer();
	if (!neutralPlayer)
		return;
	CreateMask mask;
	memset(&mask, 0, sizeof(mask));
	Team *team = neutralPlayer->getDefaultTeam();
	Object *vision = TheThingFactory->newObject(visionTemplate, team, &mask, INVALID_ID);
	if (!vision)
		return;
	m_visionObjectID = vision->m_id;
	vision->setPosition(owner->getPosition());
	vision->setShroudClearingRange(owner->m_geometryInfo.m_minorRadius);
}

