BattlePlanUpdate::BattlePlanUpdate(Thing *thing, const ModuleData *moduleData) :
	UpdateModule(thing, moduleData),
	m_bonuses(0),
	m_audioHandle(1)
{
	const BattlePlanUpdateModuleData *data = (const BattlePlanUpdateModuleData *)getModuleData();
	m_status = 0;
	m_currentPlan = 0;
	m_desiredPlan = 0;
	m_planAffectingArmy = 0;
	m_nextReadyFrame = 0;
	m_invalidSettings = false;
	m_centeringTurret = false;
	m_bonuses = new BattlePlanBonuses;
	m_bonuses->m_armorDamageFactor = 1.0f;
	m_bonuses->m_sightRangeFactor = 1.0f;
	m_bonuses->m_bombardmentActive = 0;
	m_bonuses->m_searchActive = 0;
	m_bonuses->m_holdLineActive = 0;
	m_bonuses->m_validMemberKindOf = data->m_validMemberKindOf;
	m_bonuses->m_invalidMemberKindOf = data->m_invalidMemberKindOf;
	m_visionObjectID = INVALID_ID;
	m_specialPowerModule = 0;
}

