// FUNCTION: BFME2 0x004984CC size=75 name=?cleanUp@SpectreGunshipUpdate@@QAEXXZ evidence=N:ledger tier=A
void BattlePlanUpdate::onDelete()
{
	if (m_visionObjectID) {
		GameLogic *gameLogic = TheGameLogic;
		Object *vision = gameLogic->findObjectByID(m_visionObjectID);
		if (vision)
			gameLogic->destroyObject(vision);
	}
	Player *player = getObject()->getControllingPlayer();
	if (player && m_planAffectingArmy)
		player->changeBattlePlan((BattlePlanStatus)m_planAffectingArmy, -1, m_bonuses);
}

// FUNCTION: BFME2 0x00498517 size=259 name=?xfer@BattlePlanUpdate@@MAEXPAVXfer@@@Z evidence=N:ledger tier=A
void BattlePlanUpdate::xfer(Xfer *xfer)
{
	UpdateModule::xfer(xfer);
	if (xfer->IsLightCRC())
		return;
	xfer->Version1();
	xfer->XferRawBytes(&m_currentPlan, 4);
	xfer->XferRawBytes(&m_desiredPlan, 4);
	xfer->XferRawBytes(&m_planAffectingArmy, 4);
	xfer->XferRawBytes(&m_status, 4);
	*xfer == m_nextReadyFrame;
	*xfer == m_invalidSettings;
	*xfer == m_centeringTurret;
	*xfer == m_bonuses->m_armorDamageFactor;
	*xfer == m_bonuses->m_bombardmentActive;
	*xfer == m_bonuses->m_searchActive;
	*xfer == m_bonuses->m_holdLineActive;
	*xfer == m_bonuses->m_sightRangeFactor;
	m_bonuses->m_validMemberKindOf.xfer(xfer);
	m_bonuses->m_invalidMemberKindOf.xfer(xfer);
	XferObjectID(xfer, &m_visionObjectID);
	TheAudio->xferAudioHandle(xfer, &m_audioHandle);
}

